export function mergeAuthoredPlaceScenes(baseScenes = {}, authoredScenes = AUTHORED_PLACE_SCENES) {
  const merged = { ...baseScenes };
  Object.entries(authoredScenes).forEach(([place, scene]) => {
    merged[place] = {
      ...(merged[place] || {}),
      intro: [...(merged[place]?.intro || []), ...(scene.intro || [])],
      choices: [...(merged[place]?.choices || []), ...(scene.choices || [])],
      encounters: [...(merged[place]?.encounters || []), ...(scene.encounters || [])],
    };
  });
  return merged;
}

